insert into public.products (id, name, slug, tagline, description, price, compare_at_price, brand_id, category_id, stock, rating, review_count, shipping_info, warranty, features, variants, cover_url, video_url, likes_count, comments_count, shares_count, popularity, created_at) values
  ('a0000000-0000-4000-8000-000000000001', 'PlayStation 5 Slim', 'playstation-5-slim', 'La nouvelle génération de jeu.', 'Plonge dans une nouvelle dimension de jeu avec la PS5 Slim. Plus compacte, plus puissante, une expérience encore plus immersive. SSD ultra-rapide, retour haptique et audio 3D.', 449, 599, 'b0000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000001', 18, 4.8, 12341, 'Livraison 2-4 jours', 'Garantie 2 ans', '["SSD 1 To ultra-rapide","Jeux jusqu’à 120 fps","Ray tracing","Manette DualSense incluse","Audio 3D Tempest"]'::jsonb, '[{"id":"white","label":"Couleur","value":"Blanc","colorHex":"#F4F4F8"},{"id":"black","label":"Couleur","value":"Noir","colorHex":"#111118"}]'::jsonb, 'https://images.unsplash.com/photo-1606813907291-d86efa9b94db?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4', 12400, 342, 1100, 98, now() - interval '1 days'),
  ('a0000000-0000-4000-8000-000000000002', 'Manette DualSense Midnight', 'manette-dualsense-midnight', 'Ressens chaque impact.', 'Gâchettes adaptatives, retour haptique et micro intégré. La manette qui rend chaque partie plus vivante.', 59, 74.99, 'b0000000-0000-4000-8000-000000000001', 'c0000000-0000-4000-8000-000000000001', 64, 4.7, 4210, 'Livraison 24-48h', 'Garantie 2 ans', '["Gâchettes adaptatives","Retour haptique","Micro intégré","Batterie rechargeable USB-C"]'::jsonb, '[{"id":"midnight","label":"Couleur","value":"Midnight","colorHex":"#15131F"},{"id":"white","label":"Couleur","value":"Blanc","colorHex":"#F4F4F8"}]'::jsonb, 'https://images.unsplash.com/photo-1606318801954-d46d46d3360a?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerEscapes.mp4', 5300, 128, 410, 80, now() - interval '2 days'),
  ('a0000000-0000-4000-8000-000000000003', 'Casque Gaming Pulse X', 'casque-gaming-pulse-x', 'Entends l’ennemi avant qu’il te voie.', 'Audio spatial 7.1, micro antibruit détachable et coussinets à mémoire de forme pour des sessions sans fin.', 89, 129, 'b0000000-0000-4000-8000-000000000006', 'c0000000-0000-4000-8000-000000000001', 40, 4.6, 1890, 'Livraison 2-3 jours', 'Garantie 2 ans', '["Audio spatial 7.1","Micro antibruit","Sans fil 2,4 GHz","30 h d’autonomie","Éclairage RGB"]'::jsonb, '[{"id":"black","label":"Couleur","value":"Noir","colorHex":"#111118"}]'::jsonb, 'https://images.unsplash.com/photo-1618366712010-f4ae9c647dcb?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerFun.mp4', 3100, 87, 230, 70, now() - interval '3 days'),
  ('a0000000-0000-4000-8000-000000000004', 'iPhone 16 Pro', 'iphone-16-pro', 'Titane. Puissance. Caméra pro.', 'Un design en titane, une puce surpuissante et un système photo pro pour capturer chaque détail, même de nuit.', 1129, 1329, 'b0000000-0000-4000-8000-000000000003', 'c0000000-0000-4000-8000-000000000007', 22, 4.8, 8920, 'Livraison 24-48h', 'Garantie 2 ans', '["Écran 6,3\" 120 Hz","Triple caméra 48 Mpx","Châssis titane","USB-C","Bouton Action"]'::jsonb, '[{"id":"black","label":"Couleur","value":"Titane noir","colorHex":"#2B2B30"},{"id":"natural","label":"Couleur","value":"Titane naturel","colorHex":"#BFB8AE"},{"id":"white","label":"Couleur","value":"Titane blanc","colorHex":"#E9E8E4"}]'::jsonb, 'https://images.unsplash.com/photo-1592750475338-74b7b21085ab?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerJoyrides.mp4', 9800, 410, 920, 95, now() - interval '4 days'),
  ('a0000000-0000-4000-8000-000000000005', 'AirPods Pro 2', 'airpods-pro-2', 'Le silence, version premium.', 'Réduction active du bruit jusqu’à deux fois plus efficace, audio adaptatif et boîtier MagSafe USB-C.', 229, 279, 'b0000000-0000-4000-8000-000000000003', 'c0000000-0000-4000-8000-000000000002', 55, 4.7, 15200, 'Livraison 24h', 'Garantie 2 ans', '["Réduction active du bruit","Audio spatial personnalisé","Boîtier MagSafe USB-C","6 h d’écoute"]'::jsonb, '[]'::jsonb, 'https://images.unsplash.com/photo-1600294037681-c80b4cb5b434?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerMeltdowns.mp4', 7600, 205, 640, 88, now() - interval '5 days'),
  ('a0000000-0000-4000-8000-000000000006', 'Galaxy S25 Ultra', 'galaxy-s25-ultra', 'Le zoom qui change tout.', 'Zoom 100x, stylet intégré et un écran lumineux comme jamais. Le smartphone pensé pour créer.', 1099, 1469, 'b0000000-0000-4000-8000-000000000004', 'c0000000-0000-4000-8000-000000000007', 15, 4.6, 5120, 'Livraison 24-48h', 'Garantie 2 ans', '["Capteur 200 Mpx","Zoom 100x","S Pen intégré","Écran 6,8\" QHD+","5000 mAh"]'::jsonb, '[{"id":"violet","label":"Couleur","value":"Violet","colorHex":"#5B3F8C"},{"id":"black","label":"Couleur","value":"Noir","colorHex":"#1A1A1F"}]'::jsonb, 'https://images.unsplash.com/photo-1610945265064-0e34e5519bbf?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4', 6100, 198, 512, 84, now() - interval '6 days'),
  ('a0000000-0000-4000-8000-000000000007', 'Apple Watch Series 10', 'apple-watch-series-10', 'Ta santé, au poignet.', 'Plus fine, plus grande, plus intelligente. Suivi du sommeil, ECG et détection des accidents.', 399, 449, 'b0000000-0000-4000-8000-000000000003', 'c0000000-0000-4000-8000-000000000002', 30, 4.7, 3980, 'Livraison 24-48h', 'Garantie 2 ans', '["Écran Retina toujours activé","ECG","Suivi du sommeil","Étanche 50 m"]'::jsonb, '[{"id":"42","label":"Taille","value":"42 mm"},{"id":"46","label":"Taille","value":"46 mm"}]'::jsonb, 'https://images.unsplash.com/photo-1546868871-7041f2a55e12?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerEscapes.mp4', 4200, 96, 300, 76, now() - interval '7 days'),
  ('a0000000-0000-4000-8000-000000000008', 'TV Neo QLED 65"', 'tv-neo-qled-65', 'Le cinéma s’invite au salon.', 'Mini LED, 4K 120 Hz et un son Dolby Atmos pour une immersion totale, du film au jeu vidéo.', 1199, 1799, 'b0000000-0000-4000-8000-000000000004', 'c0000000-0000-4000-8000-000000000002', 8, 4.5, 2140, 'Livraison & installation 3-5 jours', 'Garantie 3 ans', '["Dalle Mini LED 4K","120 Hz — mode jeu","Dolby Atmos","Smart TV"]'::jsonb, '[{"id":"55","label":"Taille","value":"55\""},{"id":"65","label":"Taille","value":"65\""}]'::jsonb, 'https://images.unsplash.com/photo-1593359677879-a4bb92f829d1?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerFun.mp4', 2900, 64, 180, 66, now() - interval '8 days'),
  ('a0000000-0000-4000-8000-000000000009', 'MacBook Air M4', 'macbook-air-m4', 'Fin. Silencieux. Redoutable.', 'Une autonomie de toute une journée, une puce M4 ultra-efficace et un écran Liquid Retina éclatant.', 1099, 1299, 'b0000000-0000-4000-8000-000000000003', 'c0000000-0000-4000-8000-000000000002', 12, 4.9, 6340, 'Livraison 24-48h', 'Garantie 2 ans', '["Puce M4","16 Go de mémoire","SSD 512 Go","18 h d’autonomie","Écran 13,6\""]'::jsonb, '[{"id":"midnight","label":"Couleur","value":"Minuit","colorHex":"#1E2430"},{"id":"silver","label":"Couleur","value":"Argent","colorHex":"#D9DADC"}]'::jsonb, 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerJoyrides.mp4', 5700, 150, 420, 82, now() - interval '9 days'),
  ('a0000000-0000-4000-8000-000000000010', 'Nike Air Max Pulse', 'nike-air-max-pulse', 'L’amorti qui fait la différence.', 'Une silhouette urbaine, un amorti Air visible et un confort pensé pour bouger toute la journée.', 139, 179, 'b0000000-0000-4000-8000-000000000002', 'c0000000-0000-4000-8000-000000000008', 46, 4.6, 2870, 'Livraison 2-4 jours', 'Retours 30 jours', '["Amorti Air visible","Tige en mesh respirant","Semelle caoutchouc"]'::jsonb, '[{"id":"40","label":"Pointure","value":"40"},{"id":"41","label":"Pointure","value":"41"},{"id":"42","label":"Pointure","value":"42"},{"id":"43","label":"Pointure","value":"43"},{"id":"44","label":"Pointure","value":"44"}]'::jsonb, 'https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerMeltdowns.mp4', 8800, 260, 760, 90, now() - interval '10 days'),
  ('a0000000-0000-4000-8000-000000000011', 'Adidas Ultraboost Light', 'adidas-ultraboost-light', 'Chaque foulée te renvoie l’énergie.', 'La mousse la plus légère de la gamme pour un retour d’énergie maximal, du footing au quotidien.', 129, 180, 'b0000000-0000-4000-8000-000000000005', 'c0000000-0000-4000-8000-000000000008', 38, 4.5, 1960, 'Livraison 2-4 jours', 'Retours 30 jours', '["Mousse Light Boost","Tige Primeknit","Semelle Continental"]'::jsonb, '[{"id":"41","label":"Pointure","value":"41"},{"id":"42","label":"Pointure","value":"42"},{"id":"43","label":"Pointure","value":"43"}]'::jsonb, 'https://images.unsplash.com/photo-1608231387042-66d1773070a5?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4', 3900, 101, 270, 72, now() - interval '11 days'),
  ('a0000000-0000-4000-8000-000000000012', 'Hoodie Essentials Oversize', 'hoodie-essentials-oversize', 'Le confort, en mode statement.', 'Coton brossé ultra-doux, coupe oversize et finitions premium. Le basique qui ne l’est pas.', 59, 85, 'b0000000-0000-4000-8000-000000000005', 'c0000000-0000-4000-8000-000000000003', 70, 4.4, 980, 'Livraison 2-4 jours', 'Retours 30 jours', '["80 % coton bio","Coupe oversize","Poche kangourou"]'::jsonb, '[{"id":"s","label":"Taille","value":"S"},{"id":"m","label":"Taille","value":"M"},{"id":"l","label":"Taille","value":"L"},{"id":"xl","label":"Taille","value":"XL"}]'::jsonb, 'https://images.unsplash.com/photo-1556821840-3a63f95609a7?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerEscapes.mp4', 2100, 54, 120, 58, now() - interval '12 days'),
  ('a0000000-0000-4000-8000-000000000013', 'Canapé Velours Orbit', 'canape-velours-orbit', 'Ton salon passe en première classe.', 'Velours profond, assise moelleuse et lignes arrondies. Un canapé trois places qui sublime ton intérieur.', 899, 1290, 'b0000000-0000-4000-8000-000000000007', 'c0000000-0000-4000-8000-000000000004', 6, 4.6, 412, 'Livraison 7-10 jours', 'Garantie 5 ans', '["3 places","Velours anti-taches","Pieds en chêne massif","Déhoussable"]'::jsonb, '[{"id":"violet","label":"Couleur","value":"Améthyste","colorHex":"#5A3A86"},{"id":"grey","label":"Couleur","value":"Anthracite","colorHex":"#3A3A42"}]'::jsonb, 'https://images.unsplash.com/photo-1555041469-a586c61ea9bc?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerFun.mp4', 1500, 39, 95, 50, now() - interval '13 days'),
  ('a0000000-0000-4000-8000-000000000014', 'Parfum Nuit Violette', 'parfum-nuit-violette', 'Une signature qui ne s’oublie pas.', 'Un sillage boisé et floral, mêlant violette, ambre et vanille noire. Eau de parfum 100 ml.', 79, 110, 'b0000000-0000-4000-8000-000000000008', 'c0000000-0000-4000-8000-000000000005', 50, 4.7, 1320, 'Livraison 24-48h', 'Satisfait ou remboursé', '["Eau de parfum 100 ml","Notes : violette, ambre, vanille","Tenue 10 h"]'::jsonb, '[{"id":"50","label":"Format","value":"50 ml"},{"id":"100","label":"Format","value":"100 ml"}]'::jsonb, 'https://images.unsplash.com/photo-1541643600914-78b084683601?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerJoyrides.mp4', 2600, 70, 160, 62, now() - interval '14 days'),
  ('a0000000-0000-4000-8000-000000000015', 'Séjour Bali — 7 nuits', 'sejour-bali-7-nuits', 'Rizières, plages et couchers de soleil.', 'Vols inclus, villa avec piscine privée et excursions guidées. L’évasion totale, organisée de A à Z.', 1290, 1690, 'b0000000-0000-4000-8000-000000000009', 'c0000000-0000-4000-8000-000000000006', 20, 4.8, 640, 'E-billet immédiat', 'Annulation flexible', '["Vols A/R inclus","Villa avec piscine","Petits-déjeuners","3 excursions"]'::jsonb, '[{"id":"jun","label":"Départ","value":"Juin"},{"id":"sep","label":"Départ","value":"Septembre"}]'::jsonb, 'https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerMeltdowns.mp4', 4400, 132, 610, 74, now() - interval '15 days'),
  ('a0000000-0000-4000-8000-000000000016', 'Casque Studio Wireless', 'casque-studio-wireless', 'Ta musique, sans compromis.', 'Réduction de bruit adaptative, 40 h d’autonomie et un son haute résolution signé Nova Audio.', 249, 349, 'b0000000-0000-4000-8000-000000000006', 'c0000000-0000-4000-8000-000000000002', 25, 4.6, 2310, 'Livraison 24-48h', 'Garantie 2 ans', '["Réduction de bruit adaptative","40 h d’autonomie","Hi-Res Audio","Charge rapide"]'::jsonb, '[{"id":"black","label":"Couleur","value":"Noir","colorHex":"#111118"},{"id":"white","label":"Couleur","value":"Blanc","colorHex":"#F4F4F8"}]'::jsonb, 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4', 3300, 88, 210, 68, now() - interval '16 days'),
  ('a0000000-0000-4000-8000-000000000017', 'Galaxy Buds 3 Pro', 'galaxy-buds-3-pro', 'Petits écouteurs, grand son.', 'Son Hi-Fi 24 bits, réduction de bruit intelligente et design ergonomique pour toute la journée.', 149, 229, 'b0000000-0000-4000-8000-000000000004', 'c0000000-0000-4000-8000-000000000002', 44, 4.4, 1420, 'Livraison 24-48h', 'Garantie 2 ans', '["Hi-Fi 24 bits","ANC intelligente","IP57","30 h avec boîtier"]'::jsonb, '[]'::jsonb, 'https://images.unsplash.com/photo-1590658268037-6bf12165a8df?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerEscapes.mp4', 1800, 47, 110, 55, now() - interval '17 days'),
  ('a0000000-0000-4000-8000-000000000018', 'Escapade Maldives — 5 nuits', 'escapade-maldives-5-nuits', 'Le bleu, à perte de vue.', 'Bungalow sur pilotis, pension complète et transfert en hydravion. Le luxe à l’état pur.', 2490, 3200, 'b0000000-0000-4000-8000-000000000009', 'c0000000-0000-4000-8000-000000000006', 10, 4.9, 318, 'E-billet immédiat', 'Annulation flexible', '["Bungalow sur pilotis","Pension complète","Transfert hydravion","Spa inclus"]'::jsonb, '[]'::jsonb, 'https://images.unsplash.com/photo-1514282401047-d79a71a590e8?auto=format&fit=crop&w=900&q=75', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerFun.mp4', 5200, 140, 820, 78, now() - interval '18 days')
