insert into public.drops (id, title, subtitle, description, image_url, starts_at, ends_at, is_mega) values
  ('d0000000-0000-4000-8000-000000000001', 'MEGA DROP', '10 produits d’exception à prix réduit', 'Le rendez-vous de la soirée : consoles, smartphones, audio et sneakers à prix cassés, pendant quatre heures seulement.', 'https://images.unsplash.com/photo-1606813907291-d86efa9b94db?auto=format&fit=crop&w=1200&q=75', date_trunc('day', now()) + interval '0 days' + interval '20 hours', date_trunc('day', now()) + interval '0 days' + interval '20 hours' + interval '4 hours', true),
  ('d0000000-0000-4000-8000-000000000002', 'DROP TECH', 'Le meilleur de la tech', 'Smartphones, ordinateurs et objets connectés sélectionnés par l’équipe SHOPTV.', 'https://images.unsplash.com/photo-1592750475338-74b7b21085ab?auto=format&fit=crop&w=900&q=75', date_trunc('day', now()) + interval '0 days' + interval '21 hours', date_trunc('day', now()) + interval '0 days' + interval '21 hours' + interval '3 hours', false),
  ('d0000000-0000-4000-8000-000000000003', 'DROP MODE', 'Sneakers & streetwear', 'Les paires et pièces les plus demandées de la saison, en quantités limitées.', 'https://images.unsplash.com/photo-1549298916-b41d501d3772?auto=format&fit=crop&w=900&q=75', date_trunc('day', now()) + interval '1 days' + interval '18 hours', date_trunc('day', now()) + interval '1 days' + interval '18 hours' + interval '6 hours', false),
  ('d0000000-0000-4000-8000-000000000004', 'DROP ÉVASION', 'Voyages d’exception', 'Des séjours de rêve à prix réduit, à réserver avant qu’ils ne s’envolent.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=75', date_trunc('day', now()) + interval '3 days' + interval '10 hours', date_trunc('day', now()) + interval '3 days' + interval '10 hours' + interval '24 hours', false),
  ('d0000000-0000-4000-8000-000000000005', 'FLASH GAMING', 'Accessoires gaming', 'Manettes, casques et accessoires : le setup ultime à prix flash.', 'https://images.unsplash.com/photo-1606318801954-d46d46d3360a?auto=format&fit=crop&w=900&q=75', date_trunc('day', now()) + interval '0 days' + interval '-2 hours', date_trunc('day', now()) + interval '0 days' + interval '-2 hours' + interval '30 hours', false),
  ('d0000000-0000-4000-8000-000000000006', 'DROP MAISON', 'Intérieur & bien-être', 'Mobilier et beauté pour un intérieur premium.', 'https://images.unsplash.com/photo-1555041469-a586c61ea9bc?auto=format&fit=crop&w=900&q=75', date_trunc('day', now()) + interval '-3 days' + interval '18 hours', date_trunc('day', now()) + interval '-3 days' + interval '18 hours' + interval '6 hours', false)
